import { Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { FormField, form, required, email } from '@angular/forms/signals';

import type { StoryObj } from '../../.storybook/types';

import { ButtonComponent } from './button/button';
import { CalendarComponent } from './calendar/calendar';
import { CheckboxComponent } from './checkbox/checkbox';
import { InputComponent } from './input/input';
import { RadioGroupComponent } from './radio/radio-group';
import { SelectComponent } from './select/select';
import type { SelectOption } from './select/select';
import { TextareaComponent } from './textarea/textarea';
import { AreaCodeComponent } from './area-code/area-code';

interface DemoFormModel {
  email: string;
  message: string;
  country: string | null;
  acceptTerms: boolean;
  date: Date | null;
  choice: string | null;
}

@Component({
  selector: 'ul-forms-signal-forms-demo',
  imports: [
    FormsModule,
    FormField,
    InputComponent,
    TextareaComponent,
    SelectComponent,
    CheckboxComponent,
    CalendarComponent,
    RadioGroupComponent,
    ButtonComponent,
    AreaCodeComponent,
  ],
  template: `
    <div class="ul-signal-forms-demo">
      <form (ngSubmit)="onSubmit($event)" class="ul-signal-forms-demo__form">
        <ul-input
          [formField]="demoForm.email"
          label="Email"
          type="email"
          helperText="We'll never share your email."
        />
        <ul-textarea
          [formField]="demoForm.message"
          label="Message"
          [rows]="4"
          helperText="Enter your message."
        />
        <ul-select
          [formField]="demoForm.country"
          label="Country"
          [options]="countryOptions"
          placeholder="Select country"
        />
        <ul-checkbox [formField]="demoForm.acceptTerms">
          I accept the terms and conditions
        </ul-checkbox>
        <ul-calendar [formField]="demoForm.date" label="Date" placeholder="Select date" />
        <ul-radio-group
          [formField]="demoForm.choice"
          name="choice"
          label="Choice"
          [options]="choiceOptions"
        />
        <div class="ul-signal-forms-demo__actions">
          <ul-button type="submit" theme="primary" [disabled]="!demoForm().valid()">
            Submit
          </ul-button>
        </div>
      </form>
      <aside class="ul-signal-forms-demo__values">
        <h3 class="ul-signal-forms-demo__values-title">Form value</h3>
        <ul-area-code [content]="demoValues()" [showLineNumbers]="false" />
      </aside>
    </div>
  `,
  styles: [
    `
      .ul-signal-forms-demo {
        display: flex;
        flex-direction: row;
        gap: 2rem;
        align-items: flex-start;
        max-width: 900px;
      }
      .ul-signal-forms-demo__form {
        display: flex;
        flex-direction: column;
        gap: 1rem;
        flex: 0 1 400px;
      }
      .ul-signal-forms-demo__actions {
        margin-top: 0.5rem;
      }
      .ul-signal-forms-demo__values {
        flex: 0 1 400px;
        min-width: 0;
      }
      .ul-signal-forms-demo__values-title {
        margin: 0 0 0.5rem 0;
        font-size: 0.875rem;
        font-weight: 600;
      }
    `,
  ],
})
class SignalFormsDemoComponent {
  readonly demoModel = signal<DemoFormModel>({
    email: '',
    message: '',
    country: null,
    acceptTerms: false,
    date: null,
    choice: null,
  });

  readonly demoForm = form(this.demoModel, (p) => {
    required(p.email);
    email(p.email);
    required(p.message);
    required(p.country);
    required(p.acceptTerms);
    required(p.date);
    required(p.choice);
  });

  demoValues = computed(() => {
    const value = this.demoForm().value();
    return JSON.stringify(value, null, 2);
  });

  readonly countryOptions: SelectOption[] = [
    { value: 'us', label: 'United States' },
    { value: 'uk', label: 'United Kingdom' },
    { value: 'de', label: 'Germany' },
    { value: 'fr', label: 'France' },
  ];

  readonly choiceOptions = [
    { value: 'a', label: 'Option A' },
    { value: 'b', label: 'Option B' },
    { value: 'c', label: 'Option C' },
  ];

  onSubmit(event: Event): void {
    event.preventDefault();
  }
}

export default {
  title: 'Demos/Signal Forms demo',
  component: SignalFormsDemoComponent,
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component:
          'Demo form using Angular Signal Forms with `form()`, `required()`, and `email()`. All controls (input, textarea, select, checkbox, calendar, radio-group) are bound via `[formField]`. Form value is shown live on the right. Submit is disabled when invalid.',
      },
    },
  },
};

export const SignalFormsDemo: StoryObj<SignalFormsDemoComponent> = {
  render: () => ({
    template: '<ul-forms-signal-forms-demo></ul-forms-signal-forms-demo>',
    moduleMetadata: {
      imports: [SignalFormsDemoComponent],
    },
  }),
};

import { Component, computed, signal } from '@angular/core';
import { moduleMetadata } from '@storybook/angular';

import { Meta, StoryObj } from '../../../.storybook/types';
import { CheckboxComponent } from '../checkbox/checkbox';

import { SelectableRowComponent } from './selectable-row';

interface DemoListing {
  id: number;
  title: string;
  price: string;
  imageUrl: string;
}

const DEMO_LISTINGS: DemoListing[] = [
  {
    id: 1,
    title: 'PS5 console, barely used',
    price: '$349',
    imageUrl: 'https://images.unsplash.com/photo-1607853202273-797f1c22a38e?w=200&h=200&fit=crop',
  },
  {
    id: 2,
    title: 'Mechanical keyboard, RGB',
    price: '$79',
    imageUrl: 'https://images.unsplash.com/photo-1511882150382-421056eb6909?w=200&h=200&fit=crop',
  },
  {
    id: 3,
    title: 'Racing wheel + pedals',
    price: '$210',
    imageUrl: 'https://images.unsplash.com/photo-1585504198199-20277593b94f?w=200&h=200&fit=crop',
  },
];

@Component({
  selector: 'ul-selectable-row-demo',
  imports: [SelectableRowComponent, CheckboxComponent],
  template: `
    <div
      style="min-height: 320px; padding: 1.5rem; background: var(--color-background-main, #0a0a0a);"
    >
      <div style="max-width: 420px; display: flex; flex-direction: column; gap: 12px;">
        <p style="color: rgba(255,255,255,0.7); font-size: 13px; margin: 0;">
          Resize the viewport (or use Storybook's device toolbar) to see both modes. Fine-pointer /
          real-hover viewports: hover a row to reveal its checkbox, Gmail-style. Coarse-pointer /
          no-hover viewports: long-press (or mouse-click-and-hold ~500ms) a row — it swaps the
          thumbnail for a large checkbox instead.
        </p>
        <ul-checkbox
          [checked]="allSelected()"
          [indeterminate]="someSelected()"
          (checkedChange)="toggleSelectAll($event)"
        >
          Select all
        </ul-checkbox>
        <div style="display: flex; flex-direction: column; gap: 8px;">
          @for (listing of listings; track listing.id) {
            <ul-selectable-row
              [selected]="isSelected(listing.id)"
              [selectionActive]="hasSelection()"
              [ariaLabel]="'Select ' + listing.title"
              (selectedChange)="setSelected(listing.id, $event)"
              (longPress)="select(listing.id)"
            >
              <img
                ul-selectable-row-media
                [src]="listing.imageUrl"
                alt=""
                style="width: 48px; height: 48px; flex-shrink: 0; border-radius: 6px; object-fit: cover;"
              />
              <div ul-selectable-row-content style="min-width: 0; flex: 1;">
                <p
                  style="margin: 0; color: #ffffff; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;"
                >
                  {{ listing.title }}
                </p>
                <p style="margin: 0; color: rgba(255,255,255,0.7); font-size: 13px;">
                  {{ listing.price }}
                </p>
              </div>
            </ul-selectable-row>
          }
        </div>
      </div>
    </div>
  `,
})
class SelectableRowDemoComponent {
  readonly listings = DEMO_LISTINGS;

  private readonly selectedIds = signal<ReadonlySet<number>>(new Set());
  readonly hasSelection = computed(() => this.selectedIds().size > 0);
  readonly allSelected = computed(() => this.listings.every((item) => this.isSelected(item.id)));
  readonly someSelected = computed(() => this.hasSelection() && !this.allSelected());

  isSelected(id: number): boolean {
    return this.selectedIds().has(id);
  }

  select(id: number): void {
    this.setSelected(id, true);
  }

  setSelected(id: number, value: boolean): void {
    this.selectedIds.update((current) => {
      const next = new Set(current);
      if (value) {
        next.add(id);
      } else {
        next.delete(id);
      }
      return next;
    });
  }

  toggleSelectAll(checked: boolean): void {
    this.selectedIds.set(checked ? new Set(this.listings.map((item) => item.id)) : new Set());
  }
}

const meta: Meta<SelectableRowComponent> = {
  title: 'Components/Data Display/Selectable Row',
  component: SelectableRowComponent,
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component:
          'Makes any projected row content selectable in a bulk-select list. Project a [ul-selectable-row-media] thumbnail and a [ul-selectable-row-content] label — anything else (a status pill, actions) can go in the default slot. Fine-pointer/real-hover devices get an always-present, hover-revealed checkbox (Gmail-list style); coarse-pointer/no-hover devices select via long-press instead, which swaps the media slot for a large checkbox on every row. Once selecting, a tap anywhere in the row toggles it, on any device — not just the checkbox. Bind [selected]/[selectionActive] and listen for (selectedChange)/(longPress) — the consumer still owns the actual selection Set, this component only owns the gesture/layout orchestration. It does not know about routing, so a projected routerLink anchor still needs its own binding nulled out while selectionActive, same as this tap-to-toggle relies on.',
      },
    },
  },
  decorators: [
    moduleMetadata({
      imports: [SelectableRowDemoComponent],
    }),
  ],
};

export default meta;
type Story = StoryObj<SelectableRowComponent>;

export const Default: Story = {
  render: () => ({
    template: `<ul-selectable-row-demo />`,
  }),
};

