import { Component, signal } from '@angular/core';
import { moduleMetadata } from '@storybook/angular';

import { Meta, StoryObj } from '../../../.storybook/types';
import { IconComponent } from '../icon/icon';
import { DockComponent } from './dock';
import { DockItemContentSlotDirective } from './dock-item-slot.directive';
import { DockItemComponent } from './dock-item';

@Component({
  selector: 'ul-dock-demo',
  imports: [DockComponent, DockItemComponent, IconComponent, DockItemContentSlotDirective],
  template: `
    <div style="min-height: 100vh; background: var(--color-background-main, #0a0a0a);">
      <main style="padding: 1.5rem;">
        <p style="color: rgba(255,255,255,0.7);">
          Resize the viewport below 1024px to see the dock — it's hidden by the component's own CSS
          at desktop widths, by design. The "New" item shows a fully custom, projected-content tab
          with the "accent" variant; "Alerts" shows a badge.
        </p>
      </main>
      <ul-dock>
        <ul-dock-item
          icon="home"
          label="Home"
          [active]="active() === 'home'"
          (click)="active.set('home')"
        />
        <ul-dock-item
          icon="search"
          label="Search"
          [active]="active() === 'search'"
          (click)="active.set('search')"
        />
        <ul-dock-item variant="accent" [active]="active() === 'new'" (click)="active.set('new')">
          <span ul-dock-item-content>
            <ul-icon icon="plus" size="6" />
          </span>
        </ul-dock-item>
        <ul-dock-item
          icon="bell_on"
          label="Alerts"
          badge="3"
          [active]="active() === 'alerts'"
          (click)="active.set('alerts')"
        />
        <ul-dock-item
          icon="user"
          label="Profile"
          [active]="active() === 'profile'"
          (click)="active.set('profile')"
        />
      </ul-dock>
    </div>
  `,
})
class DockDemoComponent {
  active = signal('home');
}

const meta: Meta<DockComponent> = {
  title: 'Components/Navigation/Dock',
  component: DockComponent,
  tags: ['autodocs'],
  parameters: {
    layout: 'fullscreen',
    docs: {
      description: {
        component:
          "Mobile-only bottom navigation bar (app-style tab bar). Hidden above the 'md' breakpoint (1024px) by the component's own CSS — no wrapper class or media query needed in the consuming app. Project ul-dock-item elements directly (icon + label + active state); there is no data-driven items input, since each item typically needs its own routerLink. Each item supports a badge (unread counts, etc.) and a variant ('default' | 'accent') for a raised/highlighted look, and can fully replace its icon+label with projected content via [ul-dock-item-content] for bespoke tabs. Resize the Storybook viewport below 1024px to see it render.",
      },
    },
  },
  decorators: [
    moduleMetadata({
      imports: [DockDemoComponent],
    }),
  ],
};

export default meta;
type Story = StoryObj<DockComponent>;

export const Default: Story = {
  render: () => ({
    template: `<ul-dock-demo></ul-dock-demo>`,
  }),
};

export const MobileViewport: Story = {
  ...Default,
  parameters: {
    viewport: {
      defaultViewport: 'mobile1',
    },
  },
};

export const TabletViewport: Story = {
  ...Default,
  parameters: {
    viewport: {
      defaultViewport: 'tablet',
    },
  },
};

import { Component, computed, signal } from '@angular/core';
import { moduleMetadata } from '@storybook/angular';

import { Meta, StoryObj } from '../../../.storybook/types';
import { CheckboxComponent } from '../checkbox/checkbox';

import { SelectableRowComponent } from './selectable-row';

interface DemoListing {
  id: number;
  title: string;
  price: string;
  imageUrl: string;
}

const DEMO_LISTINGS: DemoListing[] = [
  {
    id: 1,
    title: 'PS5 console, barely used',
    price: '$349',
    imageUrl: 'https://images.unsplash.com/photo-1607853202273-797f1c22a38e?w=200&h=200&fit=crop',
  },
  {
    id: 2,
    title: 'Mechanical keyboard, RGB',
    price: '$79',
    imageUrl: 'https://images.unsplash.com/photo-1511882150382-421056eb6909?w=200&h=200&fit=crop',
  },
  {
    id: 3,
    title: 'Racing wheel + pedals',
    price: '$210',
    imageUrl: 'https://images.unsplash.com/photo-1585504198199-20277593b94f?w=200&h=200&fit=crop',
  },
];

@Component({
  selector: 'ul-selectable-row-demo',
  imports: [SelectableRowComponent, CheckboxComponent],
  template: `
    <div
      style="min-height: 320px; padding: 1.5rem; background: var(--color-background-main, #0a0a0a);"
    >
      <div style="max-width: 420px; display: flex; flex-direction: column; gap: 12px;">
        <p style="color: rgba(255,255,255,0.7); font-size: 13px; margin: 0;">
          Resize the viewport (or use Storybook's device toolbar) to see both modes. Fine-pointer /
          real-hover viewports: hover a row to reveal its checkbox, Gmail-style. Coarse-pointer /
          no-hover viewports: long-press (or mouse-click-and-hold ~500ms) a row — it swaps the
          thumbnail for a large checkbox instead.
        </p>
        <ul-checkbox
          [checked]="allSelected()"
          [indeterminate]="someSelected()"
          (checkedChange)="toggleSelectAll($event)"
        >
          Select all
        </ul-checkbox>
        <div style="display: flex; flex-direction: column; gap: 8px;">
          @for (listing of listings; track listing.id) {
            <ul-selectable-row
              [selected]="isSelected(listing.id)"
              [selectionActive]="hasSelection()"
              [ariaLabel]="'Select ' + listing.title"
              (selectedChange)="setSelected(listing.id, $event)"
              (longPress)="select(listing.id)"
            >
              <img
                ul-selectable-row-media
                [src]="listing.imageUrl"
                alt=""
                style="width: 48px; height: 48px; flex-shrink: 0; border-radius: 6px; object-fit: cover;"
              />
              <div ul-selectable-row-content style="min-width: 0; flex: 1;">
                <p
                  style="margin: 0; color: #ffffff; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;"
                >
                  {{ listing.title }}
                </p>
                <p style="margin: 0; color: rgba(255,255,255,0.7); font-size: 13px;">
                  {{ listing.price }}
                </p>
              </div>
            </ul-selectable-row>
          }
        </div>
      </div>
    </div>
  `,
})
class SelectableRowDemoComponent {
  readonly listings = DEMO_LISTINGS;

  private readonly selectedIds = signal<ReadonlySet<number>>(new Set());
  readonly hasSelection = computed(() => this.selectedIds().size > 0);
  readonly allSelected = computed(() => this.listings.every((item) => this.isSelected(item.id)));
  readonly someSelected = computed(() => this.hasSelection() && !this.allSelected());

  isSelected(id: number): boolean {
    return this.selectedIds().has(id);
  }

  select(id: number): void {
    this.setSelected(id, true);
  }

  setSelected(id: number, value: boolean): void {
    this.selectedIds.update((current) => {
      const next = new Set(current);
      if (value) {
        next.add(id);
      } else {
        next.delete(id);
      }
      return next;
    });
  }

  toggleSelectAll(checked: boolean): void {
    this.selectedIds.set(checked ? new Set(this.listings.map((item) => item.id)) : new Set());
  }
}

const meta: Meta<SelectableRowComponent> = {
  title: 'Components/Data Display/Selectable Row',
  component: SelectableRowComponent,
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component:
